UPDATE PROCEDURE_LOG_MST
SET    END_DATE = CURRENT_TIMESTAMP
      ,STATUS = #{status}
      ,RESULT_CODE = #{resultCode}
      ,RESULT_MESSAGE = #{resultMessage}
WHERE  LOG_ID = #{logId}

mapper.insert:
INSERT INTO PROCEDURE_LOG_DTL (LOG_ID, SEQ, LOG_DATETIME, LOG_CONTENTS) SELECT #{logId}, NS.BASE_SEQ + V.ORD, CURRENT_TIMESTAMP, V.LOG_CONTENTS FROM (
SELECT #{i} + 1 AS ORD, #{content} AS LOG_CONTENTS
) V CROSS JOIN (SELECT COALESCE(MAX(SEQ), 0) AS BASE_SEQ FROM PROCEDURE_LOG_DTL WHERE LOG_ID = #{logId}) NS
